    class BN {
        static query(e) {
            if (this._qqWankaMap || (this._qqWankaMap = new Map),
            this._qqWankaMap.has(e))
                return this._qqWankaMap.get(e);
            let t = nk.Singleton.getDb().prepare("SELECT * FROM mst_qqwanka_meta WHERE id = $id;");
            for (t.bind({
                $id: e
            }); t.step(); ) {
                let i = t.getAsObject();
                t.free();
                let s = new kN(i);
                return this._qqWankaMap.set(e, s),
                s
            }
            return this._qqWankaMap.set(e, null),
            t.free(),
            null
        }
        static queryAll() {
            let e = []
              , t = nk.Singleton.getDb().prepare("SELECT * FROM mst_qqwanka_meta");
            for (; t.step(); )
                e.push(new kN(t.getAsObject()));
            return t.free(),
            e
        }
        static queryByKey(e) {
            let t = [];
            for (let i in e)
                t.push(`${i} = ${e[i]}`);
            let i = nk.Singleton.getDb().prepare(`SELECT * FROM mst_qqwanka_meta WHERE ${t.join(" and ")};`)
              , s = [];
            for (; i.step(); )
                s.push(new kN(i.getAsObject()));
            return i.free(),
            s
        }
        static queryOneByKey(e) {
            return this.queryByKey(e).shift()
        }
    }
